## Ejemplo: crear pedido con transaccion

`sql
START TRANSACTION;

-- Paso 1: Verificar cliente activo
SELECT id, estado FROM clientes WHERE id = 1;

-- Paso 2: Verificar producto y stock con FOR UPDATE
SELECT id, precio, stock, activo
FROM productos WHERE id IN (1, 4)
FOR UPDATE;
-- FOR UPDATE bloquea estas filas hasta COMMIT o ROLLBACK

-- Paso 3: Crear el pedido
INSERT INTO pedidos (id_cliente, fecha, estado, total, direccion_envio)
VALUES (1, CURRENT_TIMESTAMP, 'pendiente', 0, 'Calle Mayor 15, 3B, Madrid, 28001');

SET @pedido_id = LAST_INSERT_ID();

-- Paso 4: Insertar lineas
INSERT INTO linea_pedido (id_pedido, numero_linea, id_producto, cantidad, precio_unitario)
VALUES
  (@pedido_id, 1, 1, 2, 79.99),
  (@pedido_id, 2, 4, 3, 12.99);

-- Paso 5: Reducir stock
UPDATE productos SET stock = stock - 2 WHERE id = 1;
UPDATE productos SET stock = stock - 3 WHERE id = 4;

-- Paso 6: Calcular total
UPDATE pedidos
SET total = (2 * 79.99) + (3 * 12.99), estado = 'procesando'
WHERE id = @pedido_id;

-- Paso 7: Todo OK
COMMIT;
-- Si algo fallo en cualquier paso: ROLLBACK;
`

## Patron completo con manejo de errores

`sql
DELIMITER //

CREATE PROCEDURE crear_pedido_atomico(
  IN p_cliente_id INT,
  IN p_producto_id INT,
  IN p_cantidad INT,
  IN p_direccion TEXT
)
BEGIN
  DECLARE v_precio DECIMAL(10,2);
  DECLARE v_stock INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    SELECT 'ERROR: Transaccion cancelada' AS resultado;
  END;

  START TRANSACTION;

  -- Verificar cliente
  IF NOT EXISTS (SELECT 1 FROM clientes WHERE id = p_cliente_id AND estado = 'activo') THEN
    ROLLBACK;
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Cliente no valido o inactivo';
  END IF;

  -- Verificar producto y stock con FOR UPDATE
  SELECT precio, stock INTO v_precio, v_stock
  FROM productos WHERE id = p_producto_id AND activo = TRUE FOR UPDATE;

  IF v_precio IS NULL THEN
    ROLLBACK;
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Producto no valido o inactivo';
  END IF;

  IF v_stock < p_cantidad THEN
    ROLLBACK;
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Stock insuficiente';
  END IF;

  -- Crear pedido
  INSERT INTO pedidos (id_cliente, estado, total, direccion_envio)
  VALUES (p_cliente_id, 'pendiente', v_precio * p_cantidad, p_direccion);

  -- Insertar linea
  INSERT INTO linea_pedido (id_pedido, numero_linea, id_producto, cantidad, precio_unitario)
  VALUES (LAST_INSERT_ID(), 1, p_producto_id, p_cantidad, v_precio);

  -- Reducir stock
  UPDATE productos SET stock = stock - p_cantidad WHERE id = p_producto_id;

  COMMIT;
  SELECT CONCAT('Pedido #', LAST_INSERT_ID(), ' creado exitosamente') AS resultado;
END //

DELIMITER ;
`

