## Procedimiento: crear pedido

`sql
DELIMITER //

CREATE PROCEDURE crear_pedido(
  IN p_cliente_id INT,
  IN p_producto_id INT,
  IN p_cantidad INT,
  IN p_direccion TEXT
)
BEGIN
  DECLARE v_precio DECIMAL(10,2);
  DECLARE v_stock INT;
  DECLARE v_pedido_id INT;
  DECLARE v_estado_cliente VARCHAR(10);

  -- Verificar cliente activo
  SELECT estado INTO v_estado_cliente
  FROM clientes WHERE id = p_cliente_id;

  IF v_estado_cliente IS NULL THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'El cliente no existe';
  END IF;

  IF v_estado_cliente != 'activo' THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'El cliente no esta activo';
  END IF;

  -- Verificar producto y stock
  SELECT precio, stock INTO v_precio, v_stock
  FROM productos WHERE id = p_producto_id AND activo = TRUE;

  IF v_precio IS NULL THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'El producto no existe o esta inactivo';
  END IF;

  IF v_stock < p_cantidad THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Stock insuficiente';
  END IF;

  -- Crear pedido
  INSERT INTO pedidos (id_cliente, estado, total, direccion_envio)
  VALUES (p_cliente_id, 'pendiente', v_precio * p_cantidad, p_direccion);

  SET v_pedido_id = LAST_INSERT_ID();

  -- Insertar linea
  INSERT INTO linea_pedido (id_pedido, numero_linea, id_producto, cantidad, precio_unitario)
  VALUES (v_pedido_id, 1, p_producto_id, p_cantidad, v_precio);

  -- Reducir stock
  UPDATE productos SET stock = stock - p_cantidad WHERE id = p_producto_id;

  SELECT CONCAT('Pedido #', v_pedido_id, ' creado. Total: ', v_precio * p_cantidad) AS resultado;
END //

DELIMITER ;

-- Uso:
CALL crear_pedido(1, 2, 3, 'Calle Mayor 15, Madrid');
`

