UPDATE pedidos SET estado = 'enviado' WHERE id = 11;
UPDATE pedidos SET estado = 'entregado' WHERE id = 11;
UPDATE pedidos SET estado = 'pendiente' WHERE id = 11;
-- Error esperado

-- 5. Verificar auditoria
