## Pruebas de transacciones

### Prueba COMMIT
`sql
START TRANSACTION;
UPDATE productos SET stock = stock - 1 WHERE id = 1;
COMMIT;
SELECT stock FROM productos WHERE id = 1;
-- Stock debe haber disminuido en 1
`

### Prueba ROLLBACK
`sql
START TRANSACTION;
UPDATE productos SET stock = stock - 100 WHERE id = 1;
ROLLBACK;
SELECT stock FROM productos WHERE id = 1;
-- Stock debe ser el mismo que antes
`

### Prueba stock insuficiente
`sql
START TRANSACTION;
SELECT stock FROM productos WHERE id = 5 FOR UPDATE;
-- stock = 0
UPDATE productos SET stock = stock - 1 WHERE id = 5;
-- Esto viola CHECK (stock < 0)
ROLLBACK;
`

